/** Existing benchmark entry points must compose service requests and the immutable sketch profile independently. */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class ThemeQueryBenchmarkProfileContractTest {

	private static final String PROFILING = "rdf4j.benchmark.profiling";
	private static final String METADATA = "expected-db-file-sizes.properties";
	private final Map<String, String> previous = new LinkedHashMap<>();

	@BeforeEach
	void preserveProperties() {
		for (String property : new String[] { PROFILING, ThemeQueryBenchmark.WAIT_FOR_SKETCHES_PROPERTY,
				ThemeQueryBenchmark.WAIT_FOR_DIRECT_ADJACENCY_PROPERTY,
				ThemeQueryBenchmark.WAIT_FOR_VALUE_OVERLAY_PROPERTY }) {
			previous.put(property, System.getProperty(property));
		}
		System.setProperty(PROFILING, "true");
	}

	@AfterEach
	void restoreProperties() {
		previous.forEach((property, value) -> {
			if (value == null) {
				System.clearProperty(property);
			} else {
				System.setProperty(property, value);
			}
		});
	}

	@Test
	void directOnlyRequestRetainsTheDefaultQueryProfile(@TempDir Path directory) throws Exception {
		assertCompleteLoadAndReuse(directory, false, false, true, false, false);
	}

	@Test
	void overlayOnlyRequestRetainsTheDefaultQueryProfile(@TempDir Path directory) throws Exception {
		assertCompleteLoadAndReuse(directory, false, false, false, true, false);
	}

	@Test
	void sketchParameterWithoutSketchWaitingStillOwnsTheExperimentalProfile(@TempDir Path directory)
			throws Exception {
		assertCompleteLoadAndReuse(directory, true, false, false, false, false);
	}

	@Test
	void absentWaitRequestsAndFalseParameterRetainAllDefaults(@TempDir Path directory) throws Exception {
		assertCompleteLoadAndReuse(directory, false, false, false, false, true);
	}

	@ParameterizedTest
	@MethodSource("profiles")
	void requestedProfilesSurviveCompleteLoadReopenAndReuse(boolean sketchParameter, boolean waitForSketches,
			boolean waitForDirect, boolean waitForOverlay, @TempDir Path directory) throws Exception {
		assertCompleteLoadAndReuse(directory, sketchParameter, waitForSketches, waitForDirect, waitForOverlay, false);
	}

	private static Stream<Arguments> profiles() {
		return IntStream.range(0, 16)
				.mapToObj(bits -> Arguments.of((bits & 1) != 0, (bits & 2) != 0,
						(bits & 4) != 0, (bits & 8) != 0));
	}

	private static void assertCompleteLoadAndReuse(Path directory, boolean sketchParameter,
			boolean waitForSketches, boolean waitForDirect, boolean waitForOverlay, boolean absentWaitProperties)
			throws Exception {
		setRequest(ThemeQueryBenchmark.WAIT_FOR_SKETCHES_PROPERTY, waitForSketches, absentWaitProperties);
		setRequest(ThemeQueryBenchmark.WAIT_FOR_DIRECT_ADJACENCY_PROPERTY, waitForDirect, absentWaitProperties);
		setRequest(ThemeQueryBenchmark.WAIT_FOR_VALUE_OVERLAY_PROPERTY, waitForOverlay, absentWaitProperties);
		boolean sketchProfile = sketchParameter || waitForSketches;
		int[] loads = { 0 };
		ThemeQueryBenchmark benchmark = new ThemeQueryBenchmark(directory.toFile(), repository -> {
			loads[0]++;
			LmdbStore store = (LmdbStore) repository.getSail();
			assertEquals(sketchProfile, store.getQueryExecutionPolicy().experimentalQueryOptimizations(),
					"the actual loading store must select the profile from sketch intent alone");
			repository.init();
			assertEquals(!waitForDirect, "disabled".equals(store.getDirectAdjacencyReadinessDescription()),
					"direct ownership must follow its own request even with the default query profile");
			try (var connection = repository.getConnection()) {
				connection.begin();
				connection.add(Values.iri("urn:profile:subject:0"), Values.iri("urn:profile:predicate"),
						Values.literal("first"), Values.iri("urn:profile:graph:0"));
				connection.add(Values.iri("urn:profile:subject:1"), Values.iri("urn:profile:predicate"),
						Values.literal("second"), Values.iri("urn:profile:graph:1"));
				connection.commit();
				assertEquals(2L, connection.size());
			}
			assertEquals(sketchProfile, store.forceFlushSketchEstimator(),
					"the supported flush API must reach exactly the requested real sketch owner");
			if (!waitForOverlay) {
				try {
					assertFalse(store.awaitValueOverlayReady(0L, TimeUnit.NANOSECONDS),
							"an overlay-disabled loading store cannot claim a populated overlay");
				} catch (InterruptedException failure) {
					Thread.currentThread().interrupt();
					throw new IOException("Interrupted observing disabled overlay ownership", failure);
				}
			}
		});
		benchmark.themeName = "MEDICAL_RECORDS";
		benchmark.z_queryIndex = 0;
		benchmark.z_z_irMode = "disabled";
		benchmark.sketchEstimatorEnabled = sketchParameter;

		runTrial(benchmark);
		assertEquals(1, loads[0]);
		assertTrue(Files.isRegularFile(directory.resolve(METADATA)));
		assertEquals(sketchProfile, Files.isRegularFile(directory.resolve("join-estimator.rjes/synopsis-v8.bin")),
				"a successful sketch load must preserve its current reusable quad synopsis");
		Properties metadata = new Properties();
		try (var input = Files.newInputStream(directory.resolve(METADATA))) {
			metadata.load(input);
		}
		assertTrue(ThemeQueryBenchmark.hasCurrentDatasetRevision(metadata));
		assertEquals("2", metadata.getProperty("dataset.context.count"));

		runTrial(benchmark);
		assertEquals(1, loads[0], "the reopened benchmark must reuse the completed load");
		assertDataset(directory);
		runTrial(benchmark);
		assertEquals(1, loads[0], "a normal external read/reopen must preserve completed-load ownership");
	}

	private static void assertDataset(Path directory) {
		SailRepository repository = new SailRepository(new LmdbStore(directory.toFile(),
				ThemeQueryBenchmark.ConfigUtil.createConfig()));
		try (var connection = repository.getConnection()) {
			assertEquals(2L, connection.size());
			assertTrue(connection.hasStatement(Values.iri("urn:profile:subject:0"), Values.iri("urn:profile:predicate"),
					Values.literal("first"), false, Values.iri("urn:profile:graph:0")));
			assertTrue(connection.hasStatement(Values.iri("urn:profile:subject:1"), Values.iri("urn:profile:predicate"),
					Values.literal("second"), false, Values.iri("urn:profile:graph:1")));
		} finally {
			repository.shutDown();
		}
	}

	private static void runTrial(ThemeQueryBenchmark benchmark) throws IOException {
		try {
			benchmark.setup();
		} finally {
			benchmark.tearDown();
		}
	}

	private static void setRequest(String property, boolean enabled, boolean absent) {
		if (absent) {
			System.clearProperty(property);
		} else {
			System.setProperty(property, Boolean.toString(enabled));
		}
	}
}
